// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    SignerHelper maker;
    TokenHelper token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new SignerHelper();
        token = new TokenHelper();
    }

    function testFuzz_property(
        address filler,
        address to,
        uint256 nonce,
        uint256 strike,
        uint256 duration
    ) public {
        vm.assume(filler != address(0) && filler != address(maker) && filler != address(c));
        vm.assume(to != address(0) && to != address(maker) && to != address(c));
        duration = bound(duration, 0, 9_999 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 10_000 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.prank(filler);
        uint256 positionId = c.fillOrder(order, hex"00", new uint256[](0));

        // Long-call maker position token, owned by maker
        uint256 makerTokenId = uint256(c.hashOrder(order));

        vm.prank(address(maker));
        c.transferFrom(address(maker), to, makerTokenId);

        // The original owner must no longer own the token: a second transfer by them must revert.
        vm.prank(address(maker));
        bool secondOk;
        try c.transferFrom(address(maker), filler, makerTokenId) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        assertTrue(!secondOk, "original owner must not be able to transfer an already-transferred token");
    }
}

contract SignerHelper {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

